struct LoadBalancer {
    lb_id: string,
    strategy: string,
    current_index: i32,
    total_requests: i32,
    distribution_stats: any
}

fn create_load_balancer(strategy: string) -> LoadBalancer {
    let lb = LoadBalancer {
        lb_id: "lb-001",
        strategy: strategy,
        current_index: 0,
        total_requests: 0,
        distribution_stats: struct {}
    };
    return lb;
}

fn round_robin_select(services: any, lb: LoadBalancer) -> ServiceInstance {
    let len = length(services);

    if len == 0 {
        return struct {};
    }

    let selected = services[lb.current_index % len];
    lb.current_index = lb.current_index + 1;
    lb.total_requests = lb.total_requests + 1;

    return selected;
}

// ============================================================================
// Section 5: Load Balancing - Least Connection (100줄)
// ============================================================================

fn least_connection_select(services: any) -> ServiceInstance {
    let min_connections = 999999;
    let selected_service = struct {};
    let i = 0;
    let len = length(services);

    while i < len {
        let service = services[i];
        let connection_count = 0;

        // Estimate connections from metadata
        if service.metadata != {} {
            connection_count = 0;
        }

        if connection_count < min_connections {
            min_connections = connection_count;
            selected_service = service;
        }

        i = i + 1;
    }

    return selected_service;
}

