fn failover_to_next_service(registry: ServiceRegistry, service_name: string, failed_service_id: string) -> ServiceInstance {
    let services = discover_service(registry, service_name);
    let len = length(services);

    // Mark failed service as down
    perform_health_check(registry, failed_service_id, false);

    // Select next available service
    if len > 1 {
        let i = 0;
        while i < len {
            let service = services[i];
            if service.service_id != failed_service_id {
                return service;
            }
            i = i + 1;
        }
    }

    return struct {};
}

