    let stats = struct {
        registry_id: registry.registry_id,
        total_services: registry.service_count,
        healthy_services: healthy_count,
        unhealthy_services: unhealthy_count,
        health_check_count: length(registry.health_checks),
        capacity_usage: (registry.service_count * 100) / registry.max_services
    };

    return stats;
}

fn get_service_availability(registry: ServiceRegistry, service_name: string) -> i32 {
    let services = discover_service(registry, service_name);
    let all_services = any();

    // Get all services with this name (healthy and unhealthy)
    let i = 0;
    let len = length(registry.services);

    while i < len {
        let service = registry.services[i];
        if service.service_name == service_name {
            push(all_services, service);
        }
        i = i + 1;
    }

    let total = length(all_services);
    if total == 0 {
        return 0;
    }

    let healthy = length(services);
    return (healthy * 100) / total;
}

