}

fn subscribe(sub: Subscriber, topic: string) -> bool {
    push(sub.topics, topic);
    return true;
}

fn unsubscribe(sub: Subscriber, topic: string) -> bool {
    let i = 0;
    let len = length(sub.topics);
    let found = false;

    while i < len {
        if sub.topics[i] == topic {
            found = true;
        }
        i = i + 1;
    }

