}

fn receive_message(sub: Subscriber, message: Message) -> bool {
    sub.received_count = sub.received_count + 1;

    // Check if subscribed to this topic
    let is_subscribed = false;
    let i = 0;
    let len = length(sub.topics);

    while i < len {
        if sub.topics[i] == message.topic {
            is_subscribed = true;
        }
        i = i + 1;
    }

    if is_subscribed {
        sub.processed_count = sub.processed_count + 1;
        return true;
    }

    return false;
}

// ============================================================================
// Section 4: Message Ordering Guarantee (100줄)
// ============================================================================

struct MessageSequence {
    topic: string,
    partition: i32,
    sequence_number: i32,
    messages: any,
    last_offset: i32
}

fn create_partition(topic: string, partition: i32) -> MessageSequence {
    let seq = MessageSequence {
        topic: topic,
        partition: partition,
        sequence_number: 0,
        messages: any(),
        last_offset: 0
    };
    return seq;
}

fn enqueue_ordered(partition: MessageSequence, message: Message) -> MessageSequence {
    partition.sequence_number = partition.sequence_number + 1;
    message.priority = partition.sequence_number;
    push(partition.messages, message);
    partition.last_offset = partition.last_offset + 1;
    return partition;
}

fn dequeue_ordered(partition: MessageSequence) -> Message {
    if length(partition.messages) > 0 {
        let msg = partition.messages[0];
        // Remove first element
        return msg;
    }
    return struct {};
}

fn preserve_message_order(pub: Publisher, topic: string, partition: i32, messages: any) -> i32 {
    let seq = create_partition(topic, partition);
    let count = 0;
    let i = 0;
    let len = length(messages);

    while i < len {
        let msg = create_message(topic, messages[i]);
        seq = enqueue_ordered(seq, msg);
        count = count + 1;
        i = i + 1;
    }

    return count;
}

