        dlq_id: "dlq-001",
        queue: queue,
        max_retries: 3,
        retention_ms: 604800000,
        message_count: 0
    };
    return dlq;
}

fn send_to_dlq(dlq: DeadLetterQueue, message: Message) -> bool {
    message.status = "DEAD_LETTER";
    push(dlq.queue.messages, message);
    dlq.message_count = dlq.message_count + 1;
    dlq.queue.size = dlq.queue.size + 1;
    return true;
}

fn process_dlq_message(dlq: DeadLetterQueue, message: Message) -> bool {
    // Attempt reprocessing
    if message.retry_count < dlq.max_retries {
        message.retry_count = message.retry_count + 1;
        message.status = "RETRYING";
        return true;
    }

    message.status = "FAILED";
    return false;
}

fn get_dlq_size(dlq: DeadLetterQueue) -> i32 {
    return dlq.message_count;
}

// ============================================================================
// Section 6: Retry Policy (100줄)
// ============================================================================

struct MessageRetryPolicy {
    max_retries: i32,
    initial_delay: i32,
    max_delay: i32,
    backoff_type: string,
    current_retry: i32
}

fn create_retry_policy() -> MessageRetryPolicy {
    let policy = MessageRetryPolicy {
        max_retries: 3,
        initial_delay: 100,
        max_delay: 10000,
        backoff_type: "EXPONENTIAL",
        current_retry: 0
    };
    return policy;
}

fn calculate_retry_delay(policy: MessageRetryPolicy) -> i32 {
    if policy.backoff_type == "EXPONENTIAL" {
        let delay = policy.initial_delay;
        let i = 0;

        while i < policy.current_retry {
            delay = delay * 2;
            if delay > policy.max_delay {
                delay = policy.max_delay;
            }
            i = i + 1;
        }

        return delay;
    }

    return policy.initial_delay;
}

fn should_retry_message(policy: MessageRetryPolicy) -> bool {
    return policy.current_retry < policy.max_retries;
}

fn retry_message(pub: Publisher, topic: string, body: any, policy: MessageRetryPolicy) -> bool {
    while policy.current_retry < policy.max_retries {
        let delay = calculate_retry_delay(policy);
        policy.current_retry = policy.current_retry + 1;

        if publish_message(pub, topic, body) {
            return true;
        }
    }

    return false;
}

// ============================================================================
// Section 7: Queue Operations (100줄)
// ============================================================================

fn enqueue(queue: Queue, message: Message) -> bool {
    if queue.size >= queue.max_size {
        return false;
    }

    push(queue.messages, message);
    queue.size = queue.size + 1;
    queue.tail = queue.tail + 1;

    return true;
}

fn dequeue(queue: Queue) -> Message {
    if queue.size == 0 {
        return struct {};
    }

    let msg = queue.messages[queue.head];
    queue.head = queue.head + 1;
    queue.size = queue.size - 1;

    return msg;
}

fn get_queue_size(queue: Queue) -> i32 {
    return queue.size;
}

fn is_queue_full(queue: Queue) -> bool {
    return queue.size >= queue.max_size;
}

fn clear_queue(queue: Queue) -> Queue {
    queue.messages = any();
    queue.size = 0;
    queue.head = 0;
    queue.tail = 0;
    return queue;
}

