// ============================================================================
// Module 1 Tests: gRPC Protocol (T1-T8)
// ============================================================================

fn test_grpc_message_types() -> bool {
    // T1: Basic message types
    let user_msg = create_user_message();
    let is_valid = user_msg.field_count == 4;
    return is_valid;
}

fn test_grpc_field_encoding() -> bool {
    // T2: Field encoding
    let tag = encode_tag(1, WIRE_TYPE_VARINT());
    let is_valid = tag == 8;  // (1 << 3) | 0
    return is_valid;
}

fn test_grpc_tag_decoding() -> bool {
    // T3: Tag decoding
    let tag_info = decode_tag(8);
    let is_valid = tag_info.field_number == 1 && tag_info.wire_type == 0;
    return is_valid;
}

fn test_grpc_varint_encoding() -> bool {
    // T4: Varint encoding
    let encoded = encode_varint(150);
    let is_valid = length(encoded) > 0;
    return is_valid;
}

fn test_grpc_varint_decoding() -> bool {
    // T5: Varint decoding
    let encoded = encode_varint(42);
    let decoded = decode_varint(encoded, 0);
    let is_valid = decoded == 42;
    return is_valid;
}

fn test_grpc_message_serialization() -> bool {
    // T6: Message serialization
    let user = struct { id: 1, name: "Alice", email: "alice@example.com", age: 30 };
    let schema = create_user_message();
    let bytes = serialize_message(user, schema);
    let is_valid = length(bytes) > 0;
    return is_valid;
}

fn test_grpc_message_deserialization() -> bool {
    // T7: Message deserialization
    let user = struct { id: 1, name: "Bob", email: "bob@example.com", age: 25 };
    let schema = create_user_message();
    let bytes = serialize_message(user, schema);
    let decoded = deserialize_message(bytes, schema);
    let is_valid = decoded.id == 1;
    return is_valid;
}

fn test_grpc_compression() -> bool {
    // T8: Message compression
    let bytes = any();
    push(bytes, 65);
    push(bytes, 65);
    push(bytes, 65);
    push(bytes, 65);
    let compressed = compress_message(bytes);
    let is_valid = length(compressed) < length(bytes);
    return is_valid;
}

