    let server = rpc_server_create(5000);
    server = rpc_server_start(server);
    server = open_connection(server, "conn-1", "127.0.0.1:5001");
    let active = get_active_connections(server);
    let is_valid = active == 1;
    return is_valid;
}

fn test_rpc_stream_opening() -> bool {
