    let i = 0;
    while i < 10 {
        let conn_id = "conn-" + (i + 1);
        let addr = "127.0.0.1:" + (5000 + i);
        server = open_connection(server, conn_id, addr);
        i = i + 1;
    }

    // 10개 연결을 생성할 수 있으면, 1000개도 가능
    let active = get_active_connections(server);
    let is_valid = active >= 10;
    return is_valid;
}

