    let inst2 = create_service_instance("Service", "host2", 5002);
    push(services, inst1);
    push(services, inst2);

    let lb = create_load_balancer("ROUND_ROBIN");
    let selected1 = round_robin_select(services, lb);
    let selected2 = round_robin_select(services, lb);

    // 첫 번째와 두 번째 선택이 다르면 균등 분배
    let is_valid = selected1.port != selected2.port;
    return is_valid;
}

