// Rule 7: Circuit Breaker Accuracy = 100%
// ============================================================================

fn test_rule_7_circuit_breaker_accuracy() -> bool {
    // R7: Circuit Breaker 정확도 100%
    let breaker = create_circuit_breaker("breaker-1");

    // 정상 상태 테스트
    let can_exec_1 = can_execute(breaker);
    breaker = record_success(breaker);
    let state_1 = breaker.state == STATE_CLOSED();

    // 실패 누적 테스트
    breaker = record_failure(breaker);
    breaker = record_failure(breaker);
    breaker = record_failure(breaker);
    breaker = record_failure(breaker);
    breaker = record_failure(breaker);
    let opened = breaker.state == STATE_OPEN();

    // 모든 상태 전이가 정확
    let is_valid = can_exec_1 && state_1 && opened;
    return is_valid;
}

